sys_script_email.script:
(function runMailScript( /* GlideRecord */ current, /* TemplatePrinter */ template,
	/* Optional EmailOutbound */
	email, /* Optional GlideRecord */ email_action,
	/* Optional GlideRecord */
	event) {
	var jsonStr = event.parm2;
	// var json = new global.JSON();
	var jsonObject = JSON.parse(jsonStr);

	var firstName = current.first_name;
	var userName = current.user_name;
	var resetlink = jsonObject.resetPwdURL;
	var hours = Number(jsonObject.hours);
	var hoursText = hours > 1 ? " hours.</p>" : " hour.</p>";
	var title = jsonObject.title;
	var emailContent = {};
	emailContent.templateContent =
		"<p>A warmhearted hello to you, " + firstName + "!</p>" +
		"<p>&nbsp;</p>" +
		"<p>Your account was created on " + title + "!</p>" +
		"<p>Your user name is: <strong>" + userName + "</strong></p>" +
		"<p>&nbsp;</p>" +
		"<p>Along with your account is additional access to how I have configured my instance, requesting access to applications I have developed, and a number of other things. Please take your time in exploring anything that catches your interest.</p>" +
		"<p>&nbsp;</p>" +
		"<p>My goodness... I've gotten ahead of myself!!! Your account is created, but I have not given you a password!</p>" +
		"<p>Unfortunately, I cannot simply provide you one for security reasons.</p>" +
		"<p>Instead, please use the link below to do an initial password reset or use the <u><i>Forgot password</i></u> link on the log in page.</p>" +
		"<p><a href=" + resetlink + "><b><u>Set a new password</u></b></a></p>" +
		"<p><strong>NOTE:</strong> This link will expire in " + hours + hoursText +
		"<p>&nbsp;</p>" +
		"<p>Sincerely,</p>" +
		"<p>Sable N. Vimes</p>" +
		"<p>CSA | CAD | CIS-DF | CIS-ITSM</p></p>";

	email.setSubject("Set a new password to access your account");


	template.print(emailContent.templateContent);




})(current, template, email, email_action, event);
